  if (!/^[0-9]{1,20}$/.test(tenantId)) return bad("no session tenant");
  if (!/^[0-9]{1,20}$/.test(packingId)) return bad("packing_id: digits only");
  if (!/^[0-9]{1,20}$/.test(org)) return bad("organization_id: digits only");
  const ok = { route: "CONTINUE", tenantId: tenantId, packingId: packingId, organizationId: org, operation: op, idempotencyKey: key, userName: s(inp.userName).slice(0, 100), patch: {}, result_code: "", result_message: "" };
