  if (op === "STATUS") return Object.assign(ok, { route: "STATUS", idempotencyKey: "" });
  if (op !== "COMPLETE") return bad("operation must be COMPLETE or STATUS");
  if (!/^[A-Za-z0-9:_|-]{16,128}$/.test(key)) return bad("idempotency_key: 16-128 of A-Z a-z 0-9 : _ | -");
  let patch = inp.headerPatch;
  if (typeof patch === "string") {
    try {
      patch = patch ? JSON.parse(patch) : {};
    } catch (e) {
      return bad("header_patch is not valid JSON");
    }
  }
  patch = patch && typeof patch === "object" && !Array.isArray(patch) ? patch : {};
  const out = {};
  for (const k of FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(patch, k)) continue;
    const v = patch[k];
    if (v !== null && typeof v === "object") return bad("header_patch." + k + " is not a value");
    // di_freight_charges is decimal and Packing has no format node: as code_node_7u6VSG8X writes it
    if (k === "di_freight_charges") out[k] = v === null || v === undefined || s(v) === "" ? null : (parseFloat(v) || 0).toFixed(2);
    else if (k === "di_vehicle_number") out[k] = /^[0-9]{1,20}$/.test(s(v)) ? s(v) : null;
