  if (otherJob[0]) return reject("Goods Delivery " + s(f.delivery_no) + " is being saved in the background (" + (otherJob[1] || "job") + " " + otherJob[0] + "). Wait a moment, then try again.");
  const soJob = s(f.so_job).split("|");
