  // INVENTORY_APPLY_OPERATION's effect matrix: batch rows under an ITEM effect, serial rows under any effect
  if (Number(f.stray_items) > 0) return old(f.stray_items + " item(s) of this Packing have batch or serial balance rows the background save cannot move");
