  const job = (Array.isArray(rows) ? rows : rows ? [rows] : []).filter((r) => r && s(r.id))[0] || null;
  const none = { lockRows: [], needLock: "NO", packing_id: guard.packingId };
  if (!job) return Object.assign(none, { route: "REJECT", result_code: "400", result_message: "the request could not be queued; press the button again", job_id: "", job_status: "" });
  const failed = s(job.job_status) === "FAILED" || s(job.job_status) === "REQUIRES_REVIEW";
